from github3 import GitHub
import requests
import base64


class GitHubClient:
    def __init__(self, token):
        self.gh = GitHub(token=token)
        self.headers = {'Authorization': f'token {token}'}

    def search_code(self, query, sort='indexed', order='desc'):
        return self.gh.search_code(query, sort=sort, order=order)

    def get_repository(self, owner, repo_name):
        return self.gh.repository(owner, repo_name)

    def get_git_contents(self, git_url):
        """Fetch and decode git contents from raw git URL."""
        res = requests.get(git_url, headers=self.headers)
        res.raise_for_status()
        content_b64 = res.json().get('content', '')
        return base64.b64decode(content_b64).decode('utf-8')
